class LmdbPageCardinalityEstimatorDupSortNativeTest {

	private static final int LARGE_DUPLICATE_COUNT = 2_000;

	@Test
	void countsRealLmdbDupSortAndDupFixedDatabases(@TempDir Path directory) throws Exception {
		long environment = 0;
		int dupSortDbi = -1;
		int dupFixedDbi = -1;
		try {
			try (MemoryStack stack = stackPush()) {
				PointerBuffer pointer = stack.mallocPointer(1);
				check(mdb_env_create(pointer));
				environment = pointer.get(0);
				check(mdb_env_set_maxdbs(environment, 4));
				check(mdb_env_set_mapsize(environment, 64L << 20));
				check(mdb_env_open(environment, directory.toAbsolutePath().toString(), 0, 0664));

				check(mdb_txn_begin(environment, NULL, 0, pointer));
				long writeTxn = pointer.get(0);
				boolean writeTxnOpen = true;
				try {
					IntBuffer dbi = stack.mallocInt(1);
					check(mdb_dbi_open(writeTxn, "dups", MDB_CREATE | MDB_DUPSORT, dbi));
					dupSortDbi = dbi.get(0);
					check(mdb_dbi_open(writeTxn, "dupfixed", MDB_CREATE | MDB_DUPSORT | MDB_DUPFIXED, dbi));
					dupFixedDbi = dbi.get(0);

					putDuplicates(stack, writeTxn, dupSortDbi, 10, 1, Integer.BYTES);
					putDuplicates(stack, writeTxn, dupSortDbi, 20, 7, Integer.BYTES);
					putDuplicates(stack, writeTxn, dupSortDbi, 30, LARGE_DUPLICATE_COUNT, Integer.BYTES);

					putDuplicates(stack, writeTxn, dupFixedDbi, 10, 1, Long.BYTES);
					putDuplicates(stack, writeTxn, dupFixedDbi, 20, 7, Long.BYTES);
					putDuplicates(stack, writeTxn, dupFixedDbi, 30, LARGE_DUPLICATE_COUNT, Long.BYTES);

					check(mdb_txn_commit(writeTxn));
					writeTxnOpen = false;
				} finally {
					if (writeTxnOpen) {
						mdb_txn_abort(writeTxn);
					}
				}

				check(mdb_txn_begin(environment, NULL, MDB_RDONLY, pointer));
				long readTxn = pointer.get(0);
				try (LmdbPageCardinalityEstimator estimator = new LmdbPageCardinalityEstimator(
						directory.resolve("data.mdb").toFile())) {
					long txnId = mdb_txn_id(readTxn);
					long expected = 8L + LARGE_DUPLICATE_COUNT;
					assertEquals(expected, estimate(estimator, txnId, "dups", 10, 30));
					assertEquals(7, estimate(estimator, txnId, "dups", 20, 20));
					assertEquals(expected, estimate(estimator, txnId, "dupfixed", 10, 30));
					assertEquals(7, estimate(estimator, txnId, "dupfixed", 20, 20));
				} finally {
					mdb_txn_abort(readTxn);
				}
			}
		} finally {
			if (environment != 0) {
				if (dupSortDbi >= 0) {
					mdb_dbi_close(environment, dupSortDbi);
				}
				if (dupFixedDbi >= 0) {
					mdb_dbi_close(environment, dupFixedDbi);
				}
				mdb_env_close(environment);
			}
		}
	}

	private static long estimate(LmdbPageCardinalityEstimator estimator, long txnId, String databaseName,
			int minimum, int maximum) throws IOException {
		byte[] minKey = statementKey(minimum);
		byte[] maxKey = statementKey(maximum);
		return estimator.estimateEntries(txnId, databaseName, minKey, minKey.length, maxKey, maxKey.length, null);
	}

	private static void putDuplicates(MemoryStack stack, long txn, int dbi, int keyOrdinal, int duplicateCount,
			int valueSize) throws IOException {
		MDBVal key = MDBVal.malloc(stack);
		MDBVal value = MDBVal.malloc(stack);
		ByteBuffer keyBytes = stack.malloc(4);
		ByteBuffer valueBytes = stack.malloc(valueSize);
		keyBytes.put(statementKey(keyOrdinal)).flip();
		key.mv_data(keyBytes);
		for (int duplicate = 0; duplicate < duplicateCount; duplicate++) {
			valueBytes.clear();
			if (valueSize == Integer.BYTES) {
				valueBytes.putInt(duplicate);
			} else {
				valueBytes.putLong(duplicate);
			}
			valueBytes.flip();
			value.mv_data(valueBytes);
			check(mdb_put(txn, dbi, key, value, 0));
		}
	}

	private static byte[] statementKey(int value) {
		return new byte[] { (byte) value, 1, 1, 1 };
	}

	private static void check(int result) throws IOException {
		if (result != MDB_SUCCESS) {
			throw new IOException(mdb_strerror(result));
		}
	}
}
